"""Run the complete semantic-SVG-to-Cloth workflow from one file dialog.

Run this file from Blender's Text Editor.  Choose a semantic SVG containing a
PANEL group and the script will:

1. import the SVG;
2. keep and join the PANEL curves;
3. run ``001_remesh.py`` to create the triangulated cloth mesh;
4. run ``002_sew_from_svg.py`` against the same SVG; and
5. fold PANEL_LEFT/PANEL_RIGHT down around the X axis so their HEM edges end
   up at the bottom, then rotate the whole mesh IMPORT_ROTATION_Z_DEGREES
   around Z (the SVG length axis X becomes Blender Y); and
6. run ``003_cloth_setup.py`` on the generated mesh.

The implementation deliberately reuses the existing scripts so their embedded
settings remain the single source of truth.
"""

import base64
from math import cos, radians, sin
from pathlib import Path
import re
import xml.etree.ElementTree as ET
import zlib

import bpy
from bpy_extras.io_utils import ImportHelper


_PANEL_COPY_SUFFIX = re.compile(r"\.\d{3}$")
# Rotation of the folded cloth around Z, about its own center. -90 puts the
# front (the SVG +X end) at -Y, the front_axis assumed by 100_marks.py; 0 keeps
# the SVG layout (length along X).
IMPORT_ROTATION_Z_DEGREES = -90.0
SIDE_PANELS = ("PANEL_LEFT", "PANEL_RIGHT")
SIDE_PANEL_DROP = 1.0  # m the folded side panels are moved down

# Generated by scripts/tools/build_svg_to_cloth.py.  Keeping the three
# implementations inside this file makes it safe to paste into an unsaved
# Blender Text block: no repository path and no __file__ lookup is required.
