def _local_name(tag):
    return tag.rsplit("}", 1)[-1]


def _panel_ids(svg_filepath):
    """Return geometry IDs below a PANEL group or Illustrator PANEL root."""

    root = ET.parse(svg_filepath).getroot()
    ids = []
    panel_containers = []
    if (
        _local_name(root.tag) == "svg"
        and root.get("id", "").upper() == "PANEL"
    ):
        # Illustrator's basic SVG export puts the PANEL identifier on its
        # root <svg>, rather than wrapping paths in <g id="PANEL">.
        panel_containers.append(root)
    panel_containers.extend(
        element
        for element in root.iter()
        if _local_name(element.tag) == "g"
        and element.get("id", "").upper() == "PANEL"
    )
    for container in panel_containers:
        for element in container.iter():
            if element is container:
                continue
            element_id = element.get("id")
            if element_id:
                ids.append(element_id)
    if not ids:
        raise RuntimeError("SVG 中没有找到 PANEL 组内带 id 的版片路径。")
    return set(ids)


def _object_source_names(obj):
    names = {obj.name}
    if obj.data is not None:
        names.add(obj.data.name)
    return {_PANEL_COPY_SUFFIX.sub("", name) for name in names}


def _import_panel_curves(svg_filepath, panel_ids=None):
    if bpy.context.mode != "OBJECT":
        bpy.ops.object.mode_set(mode="OBJECT")

    if panel_ids is None:
        panel_ids = _panel_ids(svg_filepath)
    before = set(bpy.data.objects)
    result = bpy.ops.import_curve.svg(filepath=str(svg_filepath))
    if result != {"FINISHED"}:
        raise RuntimeError("Blender SVG 导入失败。")

    imported = [obj for obj in bpy.data.objects if obj not in before]
    panel_curves = [
        obj
        for obj in imported
        if obj.type == "CURVE" and (_object_source_names(obj) & panel_ids)
    ]
    if not panel_curves:
        imported_names = ", ".join(sorted(obj.name for obj in imported)) or "无"
        raise RuntimeError(
            "SVG 已导入，但没有找到与 PANEL 路径 id 对应的 Curve。"
            f"导入对象：{imported_names}"
        )

    # SEAM and HEM geometry is read directly from the SVG later.  Removing its
    # imported guide objects keeps the scene clean and prevents accidental joins.
    for obj in imported:
        if obj not in panel_curves:
            bpy.data.objects.remove(obj, do_unlink=True)

    bpy.ops.object.select_all(action="DESELECT")
    for curve in panel_curves:
        curve.select_set(True)
    bpy.context.view_layer.objects.active = panel_curves[0]

    if len(panel_curves) > 1:
        result = bpy.ops.object.join()
        if result != {"FINISHED"}:
            raise RuntimeError("PANEL Curve 合并失败。")

    panel = bpy.context.active_object
    panel.name = f"{Path(svg_filepath).stem}_PANELS"
    return panel


def _load_script(script_name, module_name):
    """Execute a Blender script without triggering its __main__ block."""

    namespace = {
        "__file__": f"<embedded:{script_name}>",
        "__name__": module_name,
        "__package__": None,
    }
    try:
        payload = _EMBEDDED_SCRIPTS[script_name]
    except KeyError as error:
        raise RuntimeError(f"缺少内嵌脚本：{script_name}") from error
    source = zlib.decompress(base64.b85decode(payload)).decode("utf-8-sig")
    exec(compile(source, namespace["__file__"], "exec"), namespace)
    return namespace


def _rotate_vertex_group_x(obj, group_name, angle_degrees):
    """Rotate one panel vertex group around its center on the object's X axis."""
    group = obj.vertex_groups.get(group_name)
    if group is None:
        raise RuntimeError(f"Cloth Mesh 缺少顶点组：{group_name}")

    group_index = group.index
    vertices = [
        vertex
        for vertex in obj.data.vertices
        if any(membership.group == group_index for membership in vertex.groups)
    ]
    if not vertices:
        raise RuntimeError(f"顶点组没有顶点：{group_name}")

    center_y = sum(vertex.co.y for vertex in vertices) / len(vertices)
    center_z = sum(vertex.co.z for vertex in vertices) / len(vertices)
    angle = radians(angle_degrees)
    cos_angle = cos(angle)
    sin_angle = sin(angle)

    for vertex in vertices:
        y = vertex.co.y - center_y
        z = vertex.co.z - center_z
        vertex.co.y = center_y + y * cos_angle - z * sin_angle
        vertex.co.z = center_z + y * sin_angle + z * cos_angle

    obj.data.update()


def _hem_fold_angle(obj, group_name):
    """X rotation that turns the panel's HEM edge downward (-Z).

    A rotation by a around X maps a Y offset d from the panel center to a Z
    offset d * sin(a), so the HEM goes down with a = -90 deg when it lies on
    the +Y side of the panel and a = +90 deg otherwise.
    """
    panel = obj.vertex_groups.get(group_name)
    if panel is None:
        raise RuntimeError(f"Cloth Mesh 缺少顶点组：{group_name}")
    hem_groups = {
        group.index for group in obj.vertex_groups if group.name.upper().startswith("HEM")
    }
    panel_y = []
    hem_y = []
    for vertex in obj.data.vertices:
        groups = {membership.group for membership in vertex.groups}
        if panel.index in groups:
            panel_y.append(vertex.co.y)
            if groups & hem_groups:
                hem_y.append(vertex.co.y)
    if not panel_y:
        raise RuntimeError(f"顶点组没有顶点：{group_name}")
    if not hem_y:
        raise RuntimeError(
            f"{group_name} 上没有 HEM 顶点，无法确定翻折方向；"
            "请检查 SVG 的 HEM 组。"
        )
    center_y = sum(panel_y) / len(panel_y)
    return -90.0 if sum(hem_y) / len(hem_y) > center_y else 90.0


def _rotate_mesh_z(obj, angle_degrees):
    """Rotate all vertices around Z through the mesh's XY bounds center."""
    vertices = obj.data.vertices
    if not angle_degrees or not vertices:
        return
    xs = [vertex.co.x for vertex in vertices]
    ys = [vertex.co.y for vertex in vertices]
    center_x = (min(xs) + max(xs)) / 2
    center_y = (min(ys) + max(ys)) / 2
    angle = radians(angle_degrees)
    cos_angle = cos(angle)
    sin_angle = sin(angle)
    for vertex in vertices:
        x = vertex.co.x - center_x
        y = vertex.co.y - center_y
        vertex.co.x = center_x + x * cos_angle - y * sin_angle
        vertex.co.y = center_y + x * sin_angle + y * cos_angle
    obj.data.update()


def _move_vertex_group_z(obj, group_name, distance):
    """Move one panel vertex group along the object's Z axis."""
    group = obj.vertex_groups.get(group_name)
    if group is None:
        raise RuntimeError(f"Cloth Mesh 缺少顶点组：{group_name}")

    group_index = group.index
    vertices = [
        vertex
        for vertex in obj.data.vertices
        if any(membership.group == group_index for membership in vertex.groups)
    ]
    if not vertices:
        raise RuntimeError(f"顶点组没有顶点：{group_name}")

    for vertex in vertices:
        vertex.co.z += distance

    obj.data.update()


def _ensure_front_faces_up(obj):
    """Orient flat panel faces toward +Z before folding the side panels."""
    mesh = obj.data
    mesh.update()
    for polygon in mesh.polygons:
        if polygon.normal.z < 0:
            polygon.flip()
    mesh.update()


def run_workflow(svg_filepath):
    svg_filepath = Path(svg_filepath).resolve()
    if svg_filepath.suffix.lower() != ".svg" or not svg_filepath.is_file():
        raise RuntimeError(f"请选择有效的 SVG 文件：{svg_filepath}")

    sewing = _load_script("002_sew_from_svg.py", "_cc_workflow_sew_from_svg")
    semantic_data = sewing["_semantic_svg"](str(svg_filepath))
    print(f"[CC WORKFLOW] 1/6 导入 SVG：{svg_filepath}")
    panel = _import_panel_curves(svg_filepath, set(semantic_data[0]))
    print(f"[CC WORKFLOW] 2/6 PANEL Curve 已合并：{panel.name}")

    # 001_remesh.py currently performs its work at module scope.  It leaves the new
    # cloth mesh active and selected, which is exactly the contract needed here.
    _load_script("001_remesh.py", "_cc_workflow_remesh")
    cloth = bpy.context.active_object
    if cloth is None or cloth.type != "MESH" or not cloth.get("cloth_panel_count"):
        raise RuntimeError("001_remesh.py 未生成有效的活动 Cloth Mesh。")
    print(f"[CC WORKFLOW] 3/6 Cloth Mesh 已生成：{cloth.name}")

    loose_edges = sewing["build_semantic_sewing"](
        cloth, str(svg_filepath), semantic_data=semantic_data
    )
    print(f"[CC WORKFLOW] 4/6 Sewing 已生成：{loose_edges} 条 Loose Edge")

    _ensure_front_faces_up(cloth)
    # Fold in the SVG frame first: 002 has already mapped SVG coordinates onto
    # the mesh, and folding before the Z rotation equals rotating first and
    # folding around the new length axis.
    for group_name in SIDE_PANELS:
        _rotate_vertex_group_x(cloth, group_name, _hem_fold_angle(cloth, group_name))
        _move_vertex_group_z(cloth, group_name, -SIDE_PANEL_DROP)
    _rotate_mesh_z(cloth, IMPORT_ROTATION_Z_DEGREES)
    print(
        "[CC WORKFLOW] 5/6 PANEL_LEFT/PANEL_RIGHT 向下翻折（HEM 在下方）并下移 "
        f"{SIDE_PANEL_DROP:g} m，整体绕 Z 旋转 {IMPORT_ROTATION_Z_DEGREES:g}°"
    )

    bpy.ops.object.select_all(action="DESELECT")
    cloth.select_set(True)
    bpy.context.view_layer.objects.active = cloth
    cloth_setup = _load_script(
        "003_cloth_setup.py", "_cc_workflow_cloth_setup"
    )
    cloth_setup["main"]()
    print(f"[CC WORKFLOW] 6/6 Cloth 设置完成：{cloth.name}")
    return cloth


class CC_OT_svg_cloth_workflow(bpy.types.Operator, ImportHelper):
    """选择语义 SVG 并完成导入、网格、缝合及 Cloth 设置"""

    bl_idname = "cc.svg_cloth_workflow"
    bl_label = "SVG → Cloth 完整工作流"
    bl_options = {"REGISTER", "UNDO"}
    filename_ext = ".svg"
    filter_glob: bpy.props.StringProperty(default="*.svg", options={"HIDDEN"})

    def execute(self, context):
        try:
            cloth = run_workflow(self.filepath)
        except (ET.ParseError, OSError, RuntimeError, ValueError) as error:
            self.report({"ERROR"}, str(error))
            print(f"[CC WORKFLOW ERROR] {error}")
            return {"CANCELLED"}
        self.report({"INFO"}, f"完整工作流完成：{cloth.name}")
        return {"FINISHED"}


def launch_svg_dialog():
    previous = getattr(bpy.types, CC_OT_svg_cloth_workflow.__name__, None)
    if previous is not None:
        try:
            bpy.utils.unregister_class(previous)
        except RuntimeError:
            pass
    bpy.utils.register_class(CC_OT_svg_cloth_workflow)
    if bpy.app.background:
        raise RuntimeError("后台模式请直接调用 run_workflow(svg_filepath)。")
    return bpy.ops.cc.svg_cloth_workflow("INVOKE_DEFAULT")


if __name__ == "__main__":
    launch_svg_dialog()
